48	     *          |      +-------+-------+           |
49	     *          |              |                   |
50	     *          |              v                   |
51	     *          |      +-------+-------+           |
52	     *          +----- | Restoring (1) | <---+     |
53	     *          |      +-------+-------+     |     |
54	     *          |              |             |     |
55	     *          |              v             |     |
56	     *          |      +-------+-------+     |     |
57	     *          |      |  Running (2)  |     |     |
58	     *          |      +-------+-------+     |     |
59	     *          |              |             |     |
60	     *          |              v             |     |
61	     *          |     +--------+-------+     |     |
62	     *          +---> |  Suspended (3) | ----+     |    //TODO Suspended(3) could be removed after we've stable on KIP-429
63	     *                +--------+-------+           |
64	     *                         |                   |
65	     *                         v                   |
66	     *                +--------+-------+           |
67	     *                |   Closed (4)   | ----------+
68	     *                +----------------+
69	     * </pre>
70	     */
71	    enum State {
72	        CREATED(1, 3),            // 0
73	        RESTORING(2, 3),          // 1
74	        RUNNING(3),               // 2
75	        SUSPENDED(1, 4),          // 3
76	        CLOSED(0);                // 4, we allow CLOSED to transit to CREATED to handle corrupted tasks
